SELECT segment, CASE WHEN credit_limit >= 16900 THEN 'high' WHEN credit_limit >= 8100 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, CASE WHEN age >= 62 THEN 'high' WHEN age >= 34 THEN 'mid' ELSE 'low' END AS age_bucket, MAX(age) - MIN(age) AS age_range, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(segment))) AS segment_values FROM customers WHERE MONTH(signup_date) IN (1, 9, 10) GROUP BY segment, CASE WHEN credit_limit >= 16900 THEN 'high' WHEN credit_limit >= 8100 THEN 'mid' ELSE 'low' END, CASE WHEN age >= 62 THEN 'high' WHEN age >= 34 THEN 'mid' ELSE 'low' END;
